#!/bin/sh
backup_menu(){ while :; do c=$(ui_menu Backup "Directory: $BACKUP_DIR" common 'Back up common configuration' archive 'Create compressed backup' list 'List backups' restore 'Restore a backup file' clean 'Delete backups older than 30 days' log 'View operation log') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in common) backup_common;; archive) backup_common; d=$(ls -dt "$BACKUP_DIR"/config-* 2>/dev/null|head -1); [ -n "$d" ] && tar -czf "$d.tar.gz" -C "$BACKUP_DIR" "$(basename "$d")";; list) ui_text Backups "$(ls -lht "$BACKUP_DIR" 2>/dev/null)";; restore) f=$(ui_input Restore 'Backup file:' '') || continue; t=$(ui_input Restore 'Destination:' '') || continue; [ -f "$f" ] && { backup_file "$t"; as_root cp -p "$f" "$t"; };; clean) find "$BACKUP_DIR" -type f -mtime +30 -delete;; log) ui_text Log "$(tail -n 200 "$LOG_FILE")";; esac; done; }
backup_common(){ d="$BACKUP_DIR/config-$(date +%Y%m%d-%H%M%S)"; mkdir -p "$d/home" "$d/etc"; for f in .profile .bashrc .zshrc .ashrc .aliases .nanorc .vimrc .inputrc .gitconfig .tmux.conf; do [ -e "$CURRENT_HOME/$f" ] && cp -p "$CURRENT_HOME/$f" "$d/home/"; done; for f in hosts resolv.conf hostname profile environment; do [ -e "/etc/$f" ] && as_root cp -p "/etc/$f" "$d/etc/"; done; for x in ssh apt apk pacman.d; do [ -e "/etc/$x" ] && as_root cp -Rp "/etc/$x" "$d/etc/"; done; ui_msg Backup "$d"; }
